+        this.certificate = Objects.requireNonNull(certificate, "Certificate may not be null");
+        this.path = path;
+        this.format = Objects.requireNonNull(format, "Format may not be null");
+        this.alias = alias;
+        this.hasPrivateKey = hasPrivateKey;
+    }
