+            .field(Fields.NODE, shardRouting.currentNodeId())
+            .field(Fields.RELOCATING_NODE, shardRouting.relocatingNodeId())
+            .endObject();
+        builder.field(Fields.STATS, stats, params);
+        builder.endObject();
+        return builder;
+    }
+
+    static final class Fields {
